{"content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { resolveConfig, formatConfig, formatLegacy } from './src/index.mjs';
import { DEFAULTS } from './src/defaults.mjs';

test('defaults resolve and old format is preserved', () => {
  const config = resolveConfig();
  assert.deepEqual(config, { network: { endpoint: 'localhost', retries: 3 }, ui: { theme: 'light', compact: false }, enabled: true });
  assert.equal(formatLegacy(config), 'endpoint=localhost;retries=3;enabled=on');
  assert.equal(formatConfig(config), 'endpoint=localhost;retries=3;enabled=on;theme=light;compact=no');
});

test('file fields merge with nested defaults', () => {
  assert.deepEqual(resolveConfig({ file: { network: { endpoint: 'api.local' }, ui: { compact: true } } }),
    { network: { endpoint: 'api.local', retries: 3 }, ui: { theme: 'light', compact: true }, enabled: true });
});

test('env wins over file, including zero and false', () => {
  const config = resolveConfig({ file: { network: { retries: 7 }, enabled: true },
    env: { APP_RETRIES: '00', APP_ENABLED: 'false' } });
  assert.equal(config.network.retries, 0);
  assert.equal(config.enabled, false);
});

test('ordinary service utilities retain their behavior', async () => {
  const [{ normalizeServiceId }, { cacheKey }, { parseLogLevel }] = await Promise.all([
    import('./src/id.mjs'), import('./src/cache-key.mjs'), import('./src/log-level.mjs')]);
  assert.equal(cacheKey(normalizeServiceId('  Billing API '), 2), 'billing-api:2');
  assert.equal(parseLogLevel('WARN'), 'warn');
});

test('no state leak between calls and defaults untouched', () => {
  const before = JSON.stringify(DEFAULTS);
  resolveConfig({ file: { network: { endpoint: 'x' }, ui: { theme: 'dark' }, enabled: false } });
  assert.equal(JSON.stringify(DEFAULTS), before);
  assert.deepEqual(resolveConfig(), { network: { endpoint: 'localhost', retries: 3 }, ui: { theme: 'light', compact: false }, enabled: true });
});

test('no nested reference retained from file layer', () => {
  const file = { network: { endpoint: 'a' }, ui: { theme: 'b' } };
  const config = resolveConfig({ file });
  file.network.endpoint = 'mutated';
  file.ui.theme = 'mutated';
  assert.equal(config.network.endpoint, 'a');
  assert.equal(config.ui.theme, 'b');
});

test('invalid env values throw TypeError', () => {
  assert.throws(() => resolveConfig({ env: { APP_RETRIES: 'abc' } }), TypeError);
  assert.throws(() => resolveConfig({ env: { APP_RETRIES: '-1' } }), TypeError);
  assert.throws(() => resolveConfig({ env: { APP_RETRIES: '1.5' } }), TypeError);
  assert.throws(() => resolveConfig({ env: { APP_COMPACT: 'yes' } }), TypeError);
  assert.throws(() => resolveConfig({ env: { APP_ENABLED: '1' } }), TypeError);
  assert.throws(() => resolveConfig({ env: { APP_ENDPOINT: '' } }), TypeError);
});

test('invalid layer objects throw TypeError', () => {
  assert.throws(() => resolveConfig({ file: null }), TypeError);
  assert.throws(() => resolveConfig({ file: [] }), TypeError);
  assert.throws(() => resolveConfig({ env: null }), TypeError);
  assert.throws(() => resolveConfig({ env: [] }), TypeError);
});

test('missing env keys have no effect, other keys ignored', () => {
  assert.deepEqual(resolveConfig({ env: { OTHER: 'x' } }),
    { network: { endpoint: 'localhost', retries: 3 }, ui: { theme: 'light', compact: false }, enabled: true });
});

test('max safe integer retries accepted', () => {
  const config = resolveConfig({ env: { APP_RETRIES: String(Number.MAX_SAFE_INTEGER) } });
  assert.equal(config.network.retries, Number.MAX_SAFE_INTEGER);
});
